import os, re, pathlib, collections
env = {}
for line in open('.env', encoding='utf-8', errors='ignore'):
    line=line.strip()
    if not line or line.startswith('#') or '=' not in line: continue
    k,v = line.split('=',1)
    v=v.strip().strip('"').strip("'")
    if len(v) >= 8: env[k.strip()] = v

state = pathlib.Path(os.path.expanduser('~/.claude/projects/C--Users-Sreekaran-Desktop-Major-Project'))
files = sorted(state.rglob('*.jsonl')) + sorted(state.rglob('*.txt')) + sorted(state.rglob('*.md'))
hits = collections.Counter()
per_file = collections.defaultdict(set)
for f in files:
    try: text = f.read_text(encoding='utf-8', errors='ignore')
    except Exception: continue
    for k,v in env.items():
        n = text.count(v)
        if n:
            hits[k]+=n
            per_file[f.name].add(k)

print("secrets defined in .env:", len(env), "->", ", ".join(env))
print()
