import os, re, pathlib, collections
state = pathlib.Path(os.path.expanduser('~/.claude/projects/C--Users-Sreekaran-Desktop-Major-Project'))
pats = {
 'GitHub token'   : re.compile(r'gh[pousr]_[A-Za-z0-9]{30,}'),
 'HuggingFace tok': re.compile(r'hf_[A-Za-z0-9]{30,}'),
 'Groq key'       : re.compile(r'gsk_[A-Za-z0-9]{40,}'),
 'Google API key' : re.compile(r'AIza[0-9A-Za-z_\-]{30,}'),
 'OpenAI key'     : re.compile(r'sk-[A-Za-z0-9_\-]{20,}'),
 'AWS access key' : re.compile(r'AKIA[0-9A-Z]{16}'),
 'postgres URL'   : re.compile(r'postgres(?:ql)?://[^\s"\\\']{10,}'),
 'Bearer token'   : re.compile(r'Bearer\s+[A-Za-z0-9_\-\.]{25,}'),
 'private key'    : re.compile(r'-----BEGIN [A-Z ]*PRIVATE KEY-----'),
}
found = collections.defaultdict(collections.Counter)
for f in sorted(state.rglob('*')):
    if not f.is_file(): continue
    try: text = f.read_text(encoding='utf-8', errors='ignore')
    except Exception: continue
    for name, rx in pats.items():
        vals = set(rx.findall(text))
        if vals: found[name][f.name] = len(vals)

if not found:
    print("no additional credential patterns matched")
for name, files in found.items():
    print(f"{name}:")
    for fn, n in files.items(): print(f"   {fn}  ({n} distinct)")
